                H.vector(zeroExtendingResizing: a),
                H.Vector(raw: HighwayReference.vectorZeroExtendingResizingHalfI64ToU16(a.raw)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }
}
